import{bV as e,aL as a,u as s,G as _}from"./chunks/framework.DxlKcdLe.js";const f=JSON.parse('{"title":"你知道的越多，不知道的也就越多","description":"","frontmatter":{"title":"你知道的越多，不知道的也就越多","date":"2020-05-06T15:52:40.000Z","permalink":"/pages/f2e63f","sidebar":"auto","categories":["随笔"],"tags":["学习","知识","鸡汤"]},"headers":[],"relativePath":"pages/f2e63f.md","filePath":"_posts/随笔/你知道的越多，不知道的也就越多.md","lastUpdated":1785140148000}'),p={name:"pages/f2e63f.md"};function o(c,t,i,r,l,d){return a(),s("div",null,[...t[0]||(t[0]=[_('<h1 id="你知道的越多-不知道的也就越多" tabindex="-1">你知道的越多，不知道的也就越多 <a class="header-anchor" href="#你知道的越多-不知道的也就越多" aria-label="Permalink to &quot;你知道的越多，不知道的也就越多&quot;">​</a></h1><p>不知道大家有没有发现，我们身边经常有这样的人，他们越是有能力的，越是有知识的，越是低调，越是谦逊，因为他们深知，知道的越多，不知道的也就越多。</p><p>你知道的越多，你不知道的也就越多，这是一句非常有哲理的话。</p><p>每个人的知识面都是有限的，你有可能在某个领域会有较深的研究，成为这个领域里的专家，等到你站在高处的时候，才会发现，自己是多么的渺小，才知道自己有多少没有涉及的领域。知道的越多，疑惑、问题就会越来越多，对已知的质疑、疑虑、困惑就会越来越多。</p><p>即使如此，我们也应该努力，至少可以成为某个领域的佼佼者。</p><div class="tip custom-block"><p class="custom-block-title">鸡汤1</p><p>弱小的人，才习惯嘲讽与否定，而内心强大的人，从不吝啬赞美与鼓励。</p></div><div class="tip custom-block"><p class="custom-block-title">鸡汤2</p><p>当代青年人都应该摆脱冷气，只管向上走，不必听从自暴自弃者的流言。能做事的做事，能发声的发声。有一份热，发一份光，就像萤火一般，也可以在黑暗里发一点光，不必等候炬火。</p></div>',7)])])}const m=e(p,[["render",o]]);export{f as __pageData,m as default};
